<?php require __DIR__.'/../components/dashboard_components.php'; ?>
<?php $canWriteVideoNotes = isset($room) && $room && (int) $user['id'] === (int) $room['counsellor_id']; ?>
<!doctype html><html lang="en" class="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?= h($_SESSION['csrf_token']) ?>"><title>Video Consultation · ThriveWell OS</title><link rel="stylesheet" href="/build/app.css"><script defer src="/build/app.js"></script></head>
<body><main class="video-page"><section class="video-hero card"><span class="eyebrow">Native video consultation</span><h1>A private therapeutic room, not a generic call.</h1><p>Waiting room, device checks, captions, low-bandwidth mode, consent-before-recording, crisis handoff, notes, and editable AI summaries are prepared with human-first safety.</p><a class="link-inline" href="/booking">← Back to booking</a><div class="video-room-list"><?php foreach ($rooms as $item): ?><a class="video-room-chip <?= $room && (int) $room['id'] === (int) $item['id'] ? 'active' : '' ?>" href="/video?room=<?= h((string) $item['id']) ?>"><strong><?= h($item['client_name']) ?></strong><span><?= h(date('M j, g:i A', strtotime($item['starts_at']))) ?> · <?= h($item['session_format']) ?></span></a><?php endforeach; ?></div></section>
<?php if (!$room): ?><section class="card video-stage"><?php empty_state('No video room selected', 'Choose a scheduled room to prepare safely.'); ?></section><?php else: ?>
<section class="card video-stage"><div class="card-head"><div><span class="eyebrow">Waiting room</span><h2><?= h($room['client_name']) ?> with <?= h($room['counsellor_name']) ?></h2></div><?= status_pill($room['status']) ?></div><div class="video-canvas" role="img" aria-label="Private video consultation preview"><div class="participant primary"><img src="<?= h($room['client_avatar']) ?>" alt=""><strong><?= h($room['client_name']) ?></strong><span>Client · <?= h($room['session_format']) ?></span></div><div class="participant"><img src="<?= h($room['counsellor_avatar']) ?>" alt=""><strong><?= h($room['counsellor_name']) ?></strong><span>Counsellor</span></div><div class="video-controls"><button type="button">Audio only</button><button type="button">Low bandwidth</button><button type="button">Captions</button><button type="button">Join when open</button></div></div><div class="video-safety-grid"><div><strong>Join window</strong><span><?= h($room['join_window']['copy']) ?></span></div><div><strong>Recording consent</strong><span><?= h($room['safety']['recording']) ?> Current: <?= h($room['recording_status']) ?></span></div><div><strong>AI safety</strong><span><?= h($room['safety']['ai_summary']) ?></span></div><div><strong>Crisis</strong><span><?= h($room['safety']['crisis']) ?></span></div></div></section>
<section class="card video-panel"><div class="card-head"><h2>Device check</h2><span>Accessible setup</span></div><div class="state-strip" aria-live="polite"><div class="success-state" hidden>Saved.</div><div class="error-state" hidden>Check details.</div></div><form data-async-form action="/video/device-check" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="video_consultation_room_id" value="<?= h((string) $room['id']) ?>"><label>Camera<select name="camera_status"><option value="ready">Ready</option><option value="blocked">Blocked</option><option value="audio_only">Audio only</option></select></label><label>Microphone<select name="microphone_status"><option value="ready">Ready</option><option value="muted">Muted</option><option value="needs_help">Needs help</option></select></label><label>Network<select name="network_status"><option value="stable">Stable</option><option value="low_bandwidth">Low bandwidth</option></select></label><label class="inline-check"><input type="checkbox" name="caption_enabled" checked> Captions</label><label class="inline-check"><input type="checkbox" name="low_bandwidth_mode"> Low bandwidth mode</label><button type="submit">Save device check</button></form></section>
<section class="card video-panel"><div class="card-head"><h2>Consent before recording</h2><span>Disabled by default</span></div><form data-async-form action="/video/consent" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="video_consultation_room_id" value="<?= h((string) $room['id']) ?>"><label class="inline-check"><input type="checkbox" name="granted"> I consent to recording for this session only</label><button type="submit">Save consent choice</button></form><?php foreach ($room['recording_consents'] as $consent): ?><p class="muted">Consent <?= ((int) $consent['granted']) ? 'granted' : 'declined' ?> by user #<?= h((string) $consent['user_id']) ?> · <?= h($consent['created_at']) ?></p><?php endforeach; ?></section>
<section class="card video-panel"><div class="card-head"><h2>Session chat</h2><span>Crisis-aware</span></div><div class="video-chat"><?php foreach ($room['messages'] as $message): ?><p class="<?= (int) $message['contains_crisis_signal'] ? 'crisis-signal' : '' ?>"><strong><?= h($message['sender_name']) ?>:</strong> <?= h($message['message']) ?></p><?php endforeach; ?><?php if (!$room['messages']) empty_state('No messages yet', 'Use chat for consented session support, not emergency response.'); ?></div><form data-async-form action="/video/chat" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="video_consultation_room_id" value="<?= h((string) $room['id']) ?>"><label>Message<input name="message" placeholder="Type a supportive message"></label><button type="submit">Send message</button></form></section>
<section class="card video-panel"><div class="card-head"><h2>Clinical notes & editable AI summary</h2><span>No diagnosis · human edit required</span></div><?php if ($canWriteVideoNotes): ?><form data-async-form action="/video/notes" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="video_consultation_room_id" value="<?= h((string) $room['id']) ?>"><label>Clinical note<textarea name="notes" placeholder="Human-authored, respectful, factual note"></textarea></label><label class="inline-check"><input type="checkbox" name="shared_with_client"> Share with client after review</label><button type="submit">Save note</button></form><form data-async-form action="/video/ai-summary" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="video_consultation_room_id" value="<?= h((string) $room['id']) ?>"><label>Editable AI summary draft<textarea name="summary" placeholder="Draft only. Edit before saving. No diagnosis or medication advice."></textarea></label><button type="submit">Save editable draft</button></form><?php else: ?><?php empty_state('Notes are clinician-only', 'Clients can view shared notes after human review. AI drafts never become records without counsellor editing.'); ?><?php endif; ?><?php foreach ($room['ai_summaries'] as $summary): ?><article class="ai-summary"><strong><?= h($summary['safety_label']) ?></strong><p><?= h($summary['summary']) ?></p><?= status_pill($summary['status']) ?></article><?php endforeach; ?></section>
<?php endif; ?></main></body></html>
